#define CUT_COUNT 32
#define BEAT_COUNT 185
#define CHOICE_COUNT 22
#define STORY_FLAGS 115
#define STORY_WORDS 4   /* a hundred and twenty-eight, in four words */
#define BEAT_SAY     0
#define BEAT_WAIT    1
